import SwiftUI

struct ContentView: View {
    @EnvironmentObject private var engine: SatHunterEngine
    var body: some View { TabView() { ReceiverView().tabItem { Label("Receptor", systemImage: "radio") }; SatellitesView().tabItem { Label("Satélites", systemImage: "satellite") }; SettingsView().tabItem { Label("Configurações", systemImage: "gearshape") } }.tint(.blue) }
}
private struct ReceiverView: View {
    @EnvironmentObject private var engine: SatHunterEngine
    var running: Bool { engine.status["running"] as? Bool ?? false }; var source: String { engine.status["source"] as? String ?? "desconhecida" }; var mode: String { engine.status["mode"] as? String ?? "WFM" }; var hz: Double { engine.status["vfo_hz"] as? Double ?? 0 }
    var body: some View { NavigationStack { ScrollView { VStack(alignment: .leading, spacing: 16) { HStack { SatHunterLogo().frame(width: 56, height: 56); Label("Receptor", systemImage: "antenna.radiowaves.left.and.right").font(.title2.bold()); Spacer(); Circle().fill(running ? .green : .red).frame(width: 12) }; Text("Fonte: \(source) • \(String(format: "%.3f MHz", hz / 1e6))").foregroundStyle(.secondary); SpectrumView(values: engine.spectrum).frame(height: 180).background(Color.black).clipShape(RoundedRectangle(cornerRadius: 12)); RadarView(azimuth: engine.detail["az"] as? Double ?? 0, elevation: engine.detail["el"] as? Double ?? 0).frame(height: 220).background(Color.black).clipShape(RoundedRectangle(cornerRadius: 12)); HStack { Button(running ? "Parar" : "Iniciar") { running ? engine.stop() : engine.start() }.buttonStyle(.borderedProminent); Button("Usar demonstração") { engine.setSource("demo") }.buttonStyle(.bordered) }; Picker("Modo", selection: Binding(get: { mode }, set: { engine.setMode($0) })) { ForEach(["WFM","NFM","AM","USB","LSB","CW"], id: \.self) { Text($0).tag($0) } }.pickerStyle(.segmented); Text("Estado do núcleo").font(.headline); Text(engine.status["source_status"] as? String ?? (running ? "Executando" : "Parado")).frame(maxWidth: .infinity, alignment: .leading).padding().background(.thinMaterial).clipShape(RoundedRectangle(cornerRadius: 12)); if let err = engine.lastError { Text(err).foregroundStyle(.red) } }.padding() }.navigationTitle("SatHunter SDR") } }
}
private struct SatellitesView: View { @EnvironmentObject private var engine: SatHunterEngine; var body: some View { NavigationSplitView { List(engine.satelliteRows.indices, id: \.self) { i in let row = engine.satelliteRows[i]; let name = row["name"] as? String ?? "Satélite"; let norad = row["norad"] as? Int ?? 0; Button { engine.select(norad) } label: { VStack(alignment: .leading) { Text(name); Text("NORAD \(norad)").font(.caption).foregroundStyle(.secondary) } } }.navigationTitle("Satélites") } detail: { SatelliteDetailView() } } }
private struct SatelliteDetailView: View { @EnvironmentObject private var engine: SatHunterEngine; var body: some View { VStack(alignment: .leading, spacing: 12) { Text(engine.detail["name"] as? String ?? "Selecione um satélite").font(.title2.bold()); Text("Azimute: \(String(format: "%.1f°", engine.detail["az"] as? Double ?? 0)) • Elevação: \(String(format: "%.1f°", engine.detail["el"] as? Double ?? 0))"); Button("Começar rastreio") { engine.track(true) }.buttonStyle(.borderedProminent); Spacer() }.padding() } }
private struct SettingsView: View { @EnvironmentObject private var engine: SatHunterEngine; var body: some View { NavigationStack { Form { Section("Fonte") { Button("Demonstração") { engine.setSource("demo") }; Button("Ativar localização") { engine.location.request(); engine.location.start() }; Text("USB direto no iPad exige uma camada DriverKit ou fonte de rede.").font(.footnote).foregroundStyle(.secondary) }; Section("Diagnóstico") { Text("Satélites carregados: \(engine.satelliteRows.count)"); Text("Núcleo: \(engine.status.isEmpty ? "não inicializado" : "pronto")") } }.navigationTitle("Configurações") } } }

private struct SpectrumView: View { let values: [Float]; var body: some View { GeometryReader { geo in Path { path in guard values.count > 1 else { return }; let lo = values.min() ?? -120; let hi = max(values.max() ?? 0, lo + 1); for i in values.indices { let x = geo.size.width * CGFloat(i) / CGFloat(values.count - 1); let y = geo.size.height * CGFloat(1 - (values[i] - lo) / (hi - lo)); if i == values.startIndex { path.move(to: CGPoint(x:x,y:y)) } else { path.addLine(to: CGPoint(x:x,y:y)) } } }.stroke(.green, lineWidth: 1.5) } } }

private struct RadarView: View { let azimuth: Double; let elevation: Double; var body: some View { Canvas { context, size in let c = CGPoint(x:size.width/2,y:size.height/2); let r = min(size.width,size.height)*0.42; for factor in [1.0,0.66,0.33] { context.stroke(Path(ellipseIn:CGRect(x:c.x-r*factor,y:c.y-r*factor,width:r*2*factor,height:r*2*factor)),with:.color(.green.opacity(0.45)),lineWidth:1) }; var cross=Path(); cross.move(to:CGPoint(x:c.x-r,y:c.y)); cross.addLine(to:CGPoint(x:c.x+r,y:c.y)); cross.move(to:CGPoint(x:c.x,y:c.y-r)); cross.addLine(to:CGPoint(x:c.x,y:c.y+r)); context.stroke(cross,with:.color(.green.opacity(0.35))); let angle=(azimuth-90)*Double.pi/180; let distance=r*max(0,min(1,elevation/90)); let p=CGPoint(x:c.x+CGFloat(cos(angle)*distance),y:c.y+CGFloat(sin(angle)*distance)); context.fill(Path(ellipseIn:CGRect(x:p.x-6,y:p.y-6,width:12,height:12)),with:.color(.yellow)) } }.overlay(alignment:.topLeading) { Text("Radar  •  Az \(String(format:"%.0f",azimuth))°  El \(String(format:"%.0f",elevation))°").font(.caption).foregroundStyle(.green).padding(8) } } }
